/**
 * 당근 끌어올리기 규칙.
 *
 * 글마다 타겟 가격과 마감일이 있을 때만 가격을 내린다. 일정을 정한 날의 가격(시작가)에서
 * 타겟까지 날짜별로 균등한 직선을 긋고, 오늘 몫을 내림 단위로 맞춘다. 마지막 날은 타겟에
 * 맞춘다. 끌어올리기는 글당 15회·하루 6개 안에서, 쿨타임이 지났고 마지막 노출(끌올, 없으면 게시)이
 * 2일 이상 지난 글을 노출이 오래된 순으로 고른다. 하트 수는 같은 날짜끼리만 가른다.
 */

import { DAILY_BUMP_LIMIT, MAX_BUMPS } from "./cooldown";

/** 판매중 카드 한 장. 조회·채팅은 기록만 하고, 하트 수는 끌올 순서의 동점 처리에만 쓴다. */
export type Listing = {
	id: string;
	title: string;
	/** 지금 화면의 가격(원) */
	price: number;
	/** 하트 아이콘 옆 숫자 */
	hearts: number;
	views: number;
	chats: number;
	/** `끌올 N일 전`의 N. 끌올 문구가 없으면 null */
	bumpAgoDays: number | null;
	/** `N일 전`(게시 시점)의 N. 끌올한 적 없는 글의 노출 나이. 모르면 null */
	postedAgoDays?: number | null;
	/** 지금까지 끌어올린 횟수. 폰 문구를 못 읽었으면 null */
	bumpCount: number | null;
	/** 마지막 끌올 시각(ISO). 모르면 null */
	bumpedAt: string | null;
	/** 다음 끌올 가능 시각(ISO). 폰이 보여 준 값이 추정보다 우선한다 */
	nextBumpAt: string | null;
	/** 마감에 맞출 가격. 없으면 가격을 내리지 않는다 */
	target: number | null;
	/** 마감일 `YYYY-MM-DD`. 없으면 가격을 내리지 않는다 */
	until: string | null;
	/** 일정을 정한 날의 가격. 직선의 시작점. 없으면 지금 가격·오늘로 본다 */
	startPrice?: number | null;
	/** 일정을 정한 날 `YYYY-MM-DD` */
	startDate?: string | null;
	/** 실행에 넣는가 */
	included: boolean;
	/** 예약중 글. 끌올·가격 인하에서 빠진다 */
	reserved?: boolean;
};

/** 관리 화면에서 바꾸는 전역 설정. 가격 비율은 글의 타겟·날짜가 정한다. */
export type RuleSet = {
	dailyLimit: number;
};

export const DEFAULT_RULES: RuleSet = {
	dailyLimit: DAILY_BUMP_LIMIT,
};

/** 마지막 노출(끌올, 없으면 게시)이 이 일수 미만이면 아직 목록 위쪽이라 끌올 칸을 쓰지 않는다. */
export const MIN_BUMP_AGE_DAYS = 2;
/**
 * 마지막 노출이 이만큼 지난 글은 안 보이는 글이다. 가격만 내려도 사람이 못 보므로, 끌어올리는 날까지 인하를 미룬다.
 * 직선은 날짜로 그어져서 미룬 인하는 끌어올리는 날 한 번에 따라잡힌다.
 */
export const STALE_EXPOSURE_DAYS = 4;

export type Action = "bump" | "price-only";

/**
 * 오늘 끌올하지 못하는 까닭. 가격은 따로 내릴 수 있다.
 * fresh 마지막 노출이 2일 미만이다 / daily-limit 더 오래된 글이 하루 칸을 채웠다
 */
export type Blocked = "cooldown" | "max-bumps" | "fresh" | "daily-limit";

/** 건너뛰는 까닭. 끌올하지 못한 까닭이 있으면 그 값을 그대로 쓴다. */
export type SkipReason = "excluded" | "reserved" | Blocked;

/** 가격을 내리지 않고 끌어올리기만 하는 이유(타겟 도달). */
export type Note = "floor-reached" | null;

export type Proposal = {
	id: string;
	action: Action | "skip";
	/** 승인 가격. 내리지 않으면 현재가 */
	price: number;
	priceChanged: boolean;
	/** 오늘 인하분을 현재가 대비 %로 환산. 내리지 않으면 0 */
	ratio: number;
	skipReason: SkipReason | null;
	/** 끌어올리기 대상인데 끌올하지 못하는 까닭. 가격만 내리는 글에도 남는다 */
	blocked: Blocked | null;
	note: Note;
	/** 다음 끌올 가능 시각(ISO). 화면이 cooldown·max-bumps 안내에 쓴다 */
	nextBumpAt?: string | null;
};

export type ProposalSummary = {
	bump: number;
	priceOnly: number;
	skip: number;
	/** 끌어올리기 대상 중 하루 한도에 걸린 수 */
	held: number;
};

export type PricePoint = {
	date: string;
	price: number;
};

/**
 * 내림 단위. 경계는 인하 계산값(raw)을 기준으로 정한다.
 * 10,000원 미만 500원, 10만 원 미만 1,000원, 그 이상 5,000원.
 */
export function priceUnit(raw: number): 500 | 1000 | 5000 {
	if (raw < 10_000) return 500;
	if (raw < 100_000) return 1_000;
	return 5_000;
}

/** Asia/Seoul 달력의 `YYYY-MM-DD`. */
export function seoulToday(now = Date.now()): string {
	return new Intl.DateTimeFormat("en-CA", {
		timeZone: "Asia/Seoul",
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
	}).format(new Date(now));
}

const ISO_DAY = /^\d{4}-\d{2}-\d{2}$/;

function seoulStart(iso: string): number {
	if (!ISO_DAY.test(iso)) return Number.NaN;
	return Date.parse(`${iso}T00:00:00+09:00`);
}

/** `from`부터 `to`까지 오늘을 포함한 날 수. 날짜가 아니면 null. */
export function remainingDays(from: string, to: string): number | null {
	const start = seoulStart(from);
	const end = seoulStart(to);
	if (Number.isNaN(start) || Number.isNaN(end)) return null;
	return Math.round((end - start) / 86_400_000) + 1;
}

export function addDays(iso: string, days: number): string {
	const start = seoulStart(iso);
	if (Number.isNaN(start)) return iso;
	return seoulToday(start + days * 86_400_000);
}

/** 하루 인하폭 `step`원 이하인 가장 굵은 내림 단위. 100원보다 잘게는 내리지 않는다. */
function stepUnit(step: number): number {
	for (const unit of [5_000, 1_000, 500]) if (step >= unit) return unit;
	return 100;
}

/**
 * 시작가에서 타겟까지 `days`일에 걸쳐 균등하게 내린 `index`번째(0부터) 날의 가격.
 * 마지막 날은 타겟을 다시 내림하지 않고, 그 전에는 타겟에 닿지 않는다. 날마다 시작가로 다시 재서 내림 오차가 쌓이지 않는다.
 */
export function linePrice(start: number, target: number, index: number, days: number): number {
	const total = days < 1 ? 1 : days;
	if (target <= 0 || target >= start) return start;
	if (index + 1 >= total) return target;
	const raw = start - ((start - target) * (index + 1)) / total;
	// 하루 인하폭보다 굵은 단위로 내리면 며칠씩 멈췄다 뛰므로, 단위를 인하폭 이하(최소 100원)로 낮춰 날마다 내려가게 한다.
	const unit = Math.min(priceUnit(raw), stepUnit((start - target) / total));
	return Math.min(start, Math.max(Math.floor(raw / unit) * unit, target + unit));
}

export type Schedule = {
	price: number;
	changed: boolean;
	ratio: number;
	remainingDays: number;
};

/** 시작가·시작일이 없으면 지금 가격·오늘이 시작이다. */
function lineOf(listing: Pick<Listing, "price" | "startPrice" | "startDate">, today: string) {
	const anchored = listing.startPrice != null && listing.startPrice > 0 && listing.startDate != null;
	return {
		startPrice: anchored ? (listing.startPrice as number) : listing.price,
		startDate: anchored ? (listing.startDate as string) : today,
	};
}

/** 타겟·마감이 없거나 날짜가 아니면 가격을 바꾸지 않는다. */
export function scheduleFor(listing: Listing, today: string): Schedule {
	if (listing.target === null || listing.target <= 0 || listing.until === null) {
		return { price: listing.price, changed: false, ratio: 0, remainingDays: 0 };
	}
	const left = remainingDays(today, listing.until);
	if (left === null) return { price: listing.price, changed: false, ratio: 0, remainingDays: 0 };
	const remaining = left < 1 ? 1 : left;
	const { startPrice, startDate } = lineOf(listing, today);
	const total = remainingDays(startDate, listing.until);
	if (total === null) return { price: listing.price, changed: false, ratio: 0, remainingDays: remaining };
	// 직선이 아직 시작하지 않았다(시작일이 내일 이후). 시작일 전에는 가격을 지킨다.
	if (startDate > today) return { price: listing.price, changed: false, ratio: 0, remainingDays: remaining };
	const index = Math.max(0, total - remaining);
	const planned = linePrice(startPrice, listing.target, index, total);
	// 직선보다 이미 낮으면 올리지 않는다.
	const changed = planned < listing.price && planned > 0;
	const price = changed ? planned : listing.price;
	const ratio = changed ? (100 * (listing.price - price)) / listing.price : 0;
	return { price, changed, ratio, remainingDays: remaining };
}

/** 오늘부터 마감까지 날짜별 가격. 시작가·시작일의 직선에서 읽는다. */
export function pricePath(
	start: { price: number; date: string },
	target: number,
	until: string,
	today: string,
): PricePoint[] {
	const total = remainingDays(start.date, until);
	const left = remainingDays(today, until);
	if (total === null || left === null) return [];
	const days = left < 1 ? 1 : left;
	const points: PricePoint[] = [];
	let date = today;
	for (let step = 0; step < days; step += 1) {
		const sinceStart = remainingDays(start.date, date) ?? 1;
		// 시작일 전에는 시작가를 지킨다. 시작일부터는 직선의 (시작일 기준) 몇 번째 날인지로 읽는다.
		points.push({
			date,
			price: sinceStart < 1 ? start.price : linePrice(start.price, target, sinceStart - 1, total),
		});
		date = addDays(date, 1);
	}
	return points;
}

export type FlowPoint = PricePoint & {
	/** 지금 화면의 가격 한 점. 직선의 날짜별 가격이 아니다 */
	current?: true;
};

/**
 * 가격 흐름의 맨 앞에 지금 가격을 붙인다. 오늘 직선 가격이 지금 가격과 다르면
 * (건너뛴 날이 쌓였거나 타겟을 새로 그은 때) `오늘`만 보여 주면 지금 가격에서 어떻게 가는지 읽히지 않는다.
 */
export function flowFromNow(price: number, path: PricePoint[]): FlowPoint[] {
	if (path.length === 0) return [];
	return path[0].price === price ? path : [{ date: path[0].date, price, current: true }, ...path];
}

/** 마지막 노출 후 지난 날. 끌올 문구가 있으면 그것, 없으면 게시 시점. 둘 다 못 읽었으면 null. */
export function exposureAgeDays(listing: Pick<Listing, "bumpAgoDays" | "postedAgoDays">): number | null {
	return listing.bumpAgoDays ?? listing.postedAgoDays ?? null;
}

/** 마지막 노출이 2일 미만인가. 노출 시점을 못 읽었으면 막지 않는다. */
export function recentlyExposed(listing: Pick<Listing, "bumpAgoDays" | "postedAgoDays">): boolean {
	const age = exposureAgeDays(listing);
	return age !== null && age < MIN_BUMP_AGE_DAYS;
}

/** 마감까지 남은 날. 날짜 없거나 잘못되면 맨 뒤. 지난 마감은 오늘(1)과 같다. */
export function untilUrgency(until: string | null, today: string): number {
	if (until === null) return Number.POSITIVE_INFINITY;
	const span = remainingDays(today, until);
	if (span === null) return Number.POSITIVE_INFINITY;
	return span < 1 ? 1 : span;
}

/**
 * 끌올 칸 순서: 마지막 노출이 오래된 순(노출 시점을 못 읽은 글이 맨 앞) → 하트 적은 순 →
 * 마감 빠른 순 → 가격 높은 순 → 제목 오름차순.
 */
export function compareBumpOrder(a: Listing, b: Listing, today: string): number {
	const left = exposureAgeDays(a) ?? Number.POSITIVE_INFINITY;
	const right = exposureAgeDays(b) ?? Number.POSITIVE_INFINITY;
	if (left !== right) return left > right ? -1 : 1;
	if (a.hearts !== b.hearts) return a.hearts - b.hearts;
	const urgentA = untilUrgency(a.until, today);
	const urgentB = untilUrgency(b.until, today);
	if (urgentA !== urgentB) return urgentA - urgentB;
	if (a.price !== b.price) return b.price - a.price;
	return a.title.localeCompare(b.title, "ko");
}

/** 글당 15회를 채웠는가. */
export function atMaxBumps(listing: Pick<Listing, "bumpCount">): boolean {
	return (listing.bumpCount ?? 0) >= MAX_BUMPS;
}

/** 시각 인자. ms 숫자와 Date를 모두 받는다. */
export type Clock = number | Date;

function ms(clock: Clock): number {
	return clock instanceof Date ? clock.getTime() : clock;
}

/** 폰이 알려 준 다음 끌올 시각이 아직 지나지 않았는가. ISO가 아니면 모르는 것으로 본다. */
export function inCooldown(listing: Pick<Listing, "nextBumpAt">, now: Clock = Date.now()): boolean {
	if (listing.nextBumpAt === null) return false;
	const at = Date.parse(listing.nextBumpAt);
	return !Number.isNaN(at) && at > ms(now);
}

/** 15회 미만이고 쿨타임이 지났을 때만 끌어올릴 수 있다. */
export function bumpEligible(listing: Pick<Listing, "bumpCount" | "nextBumpAt">, now: Clock = Date.now()): boolean {
	return !atMaxBumps(listing) && !inCooldown(listing, now);
}

/** 오늘 끌어올리지 못하는 까닭. 한도 말고는 없으면 null. */
function blockedBy(listing: Listing, now: Clock): Exclude<Blocked, "daily-limit"> | null {
	if (atMaxBumps(listing)) return "max-bumps";
	if (inCooldown(listing, now)) return "cooldown";
	if (recentlyExposed(listing)) return "fresh";
	return null;
}

function bumpingIds(listings: Listing[], rules: RuleSet, today: string, now: Clock): Set<string> {
	const candidates = listings
		.filter((listing) => listing.included && !listing.reserved && blockedBy(listing, now) === null)
		.sort((left, right) => compareBumpOrder(left, right, today));
	const limit = Math.max(0, rules.dailyLimit - bumpedToday(listings, today, now));
	return new Set(candidates.slice(0, limit).map((listing) => listing.id));
}

/** 서울 날짜로 오늘 이미 끌어올린 글 수. 하루 한도는 회차가 아니라 날마다 센다. */
export function bumpedToday(listings: Pick<Listing, "bumpedAt">[], today: string, now: Clock = Date.now()): number {
	return listings.filter((listing) => {
		if (listing.bumpedAt === null) return false;
		const at = Date.parse(listing.bumpedAt);
		return !Number.isNaN(at) && at <= ms(now) && seoulToday(at) === today;
	}).length;
}

/**
 * 노출이 오래됐고 곧 끌어올릴 수 있는 글(하루 한도·쿨타임에 걸린 글)은 인하를 미룬다.
 * 15회를 채운 글은 끌어올릴 날이 없어 미루면 영영 못 내리므로 제외한다. 마감 마지막 날도 타겟에 맞춰야 해서 미루지 않는다.
 */
function holdsCutForBump(listing: Listing, blocked: Blocked, remainingDays: number): boolean {
	if (blocked !== "daily-limit" && blocked !== "cooldown") return false;
	const age = exposureAgeDays(listing);
	return age !== null && age >= STALE_EXPOSURE_DAYS && remainingDays > 1;
}

/** 지금 화면과 규칙이 고르는 글 하나의 제안. 입력 순서를 유지한다. */
export function proposeBatch(
	listings: Listing[],
	rules: RuleSet,
	today = seoulToday(),
	now: Clock = Date.now(),
): Proposal[] {
	const bumping = bumpingIds(listings, rules, today, now);

	return listings.map((listing) => {
		const scheduled = scheduleFor(listing, today);
		const base = {
			id: listing.id,
			price: scheduled.price,
			priceChanged: scheduled.changed,
			ratio: scheduled.ratio,
			nextBumpAt: listing.nextBumpAt,
		};

		if (!listing.included) {
			return { ...base, action: "skip" as const, skipReason: "excluded" as const, blocked: null, note: null };
		}

		// 예약중 글은 거래 약속이 잡혀 있다. 끌올도 가격 인하도 하지 않는다.
		if (listing.reserved) {
			return { ...base, action: "skip" as const, skipReason: "reserved" as const, blocked: null, note: null };
		}

		if (bumping.has(listing.id)) {
			return {
				...base,
				action: "bump" as const,
				skipReason: null,
				blocked: null,
				note: scheduled.changed ? null : scheduled.remainingDays > 0 ? ("floor-reached" as const) : null,
			};
		}

		// 끌올하지 못하는 글도 가격은 날마다 직선을 따라 내린다. 쿨타임이 풀릴 때까지 인하를 미루면 풀린 날 몰아서 내리게 된다.
		const blocked: Blocked = blockedBy(listing, now) ?? "daily-limit";
		if (scheduled.changed && !holdsCutForBump(listing, blocked, scheduled.remainingDays)) {
			return { ...base, action: "price-only" as const, skipReason: null, blocked, note: null };
		}
		return { ...base, action: "skip" as const, skipReason: blocked, blocked, note: null };
	});
}

export function summarize(proposals: Proposal[]): ProposalSummary {
	return proposals.reduce<ProposalSummary>(
		(summary, proposal) => {
			if (proposal.action === "skip") summary.skip += 1;
			else if (proposal.action === "bump") summary.bump += 1;
			else summary.priceOnly += 1;
			if (proposal.blocked === "daily-limit") summary.held += 1;
			return summary;
		},
		{ bump: 0, priceOnly: 0, skip: 0, held: 0 },
	);
}

/**
 * 실행 목록에 넣을 때 고정하는 글 하나의 스냅샷. 실행은 이 값과 지금 화면만 비교한다.
 * 조회 수·채팅 수는 실행 여부에 쓰지 않고 로그에만 남긴다.
 */
export type ApprovedSnapshot = {
	price: number;
	hearts: number;
	views: number;
	chats: number;
};

export type CurrentSnapshot = {
	price: number;
	hearts: number;
	views: number;
	chats: number;
};

export type SnapshotVerdict = {
	run: boolean;
	skipReason: "price-changed" | null;
	/** 지금 화면에서 읽은 값. 조회·채팅만 달라진 경우 로그에 남긴다 */
	observed: CurrentSnapshot;
	/** 조회 수·채팅 수만 달라졌는가 */
	numbersMovedOnly: boolean;
};

/** 목록의 지금 가격이 승인된 오늘 가격이면 이미 적용된 글이다. 창을 열지 않는다. */
export function alreadyAppliedToday(currentPrice: number, proposedPrice: number, snapshotPrice: number): boolean {
	return proposedPrice !== snapshotPrice && currentPrice === proposedPrice;
}

/** 실행 직전 재확인. 가격이 제안 때와 다르면 그 글만 건너뛴다. 하트·조회·채팅 변화는 기록만 한다. */
export function guardSnapshot(approved: ApprovedSnapshot, current: CurrentSnapshot): SnapshotVerdict {
	const observed = { ...current };
	if (current.price !== approved.price) {
		return { run: false, skipReason: "price-changed", observed, numbersMovedOnly: false };
	}
	const numbersMovedOnly =
		current.views !== approved.views || current.chats !== approved.chats || current.hearts !== approved.hearts;
	return { run: true, skipReason: null, observed, numbersMovedOnly };
}

