		const { phone, tapped } = fakeList(Array.from({ length: 6 }, (_, index) => `글${index}`));
		const run = runApprovedOnPhone(
			{
				id: "b",
				status: "approved" as const,
				signature: "",
				runHour: 19,
				runMinute: 0,
				approvedAt: "2026-11-07T10:00:00.000Z",
				items: [item("없는 글")],
			},
			phone,
			undefined,
			{
				log: quietLog(),
				findSerial: () => SERIAL,
				book: { previousBumpCount: () => 0, recordBump: () => {}, recordCooldown: () => {} },
			},
		);
		expect(tapped).toEqual([]);
		expect(run).toMatchObject({ bumped: 0, skipped: 1, stopped: false });
	}, 120000);
});

